  if (!employee) throw new AppError(404, 'NOT_FOUND', '员工不存在');
  if (employee.employment_status === 'terminated') throw new AppError(409, 'INVALID_STATE', '离职员工不能发起该流程');
  let targetDepartmentId = null;
