    const activeAdmins = Number(db.get(`SELECT COUNT(*) AS count FROM users WHERE role = 'admin' AND status = 'active'`).count);
    if (activeAdmins <= 1) throw new AppError(409, 'LAST_ADMIN', '系统必须保留至少一名管理员');
  }
