import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
const edge = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const outDir = 'C:/Users/16833/Documents/Codex/2026-10-12/ni/work/gsb-hr-a/review-shots';
const profile = path.join(outDir, '.profile-ui');
const child = spawn(edge, ['--headless', '--no-first-run', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,1000', '--remote-debugging-port=9340', `--user-data-dir=${profile}`, 'http://localhost:5173/login'], { stdio: 'ignore' });
const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws; let id = 0; const pending = new Map();
function cmd(method, params = {}) { return new Promise((resolve, reject) => { const n = ++id; pending.set(n, { resolve, reject }); ws.send(JSON.stringify({ id: n, method, params })); }); }
try {
  let targets;
  for (let i = 0; i < 30; i += 1) { try { targets = await (await fetch('http://localhost:9340/json')).json(); if (targets.find(t => t.type === 'page')) break; } catch {} await sleep(300); }
  const target = targets.find(t => t.type === 'page');
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  ws.onmessage = event => { const m = JSON.parse(event.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(m.error) : p.resolve(m.result); } };
  await cmd('Page.enable'); await cmd('Runtime.enable'); await cmd('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false }); await sleep(1000);
  const login = await cmd('Runtime.evaluate', { awaitPromise: true, returnByValue: true, expression: `(async()=>{
    const inputs=document.querySelectorAll('input');
    const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
    setter.call(inputs[0],'admin'); inputs[0].dispatchEvent(new Event('input',{bubbles:true}));
    setter.call(inputs[1],'Admin@123'); inputs[1].dispatchEvent(new Event('input',{bubbles:true}));
    await new Promise(r=>setTimeout(r,100));
    document.querySelector('.submit-button').click();
    await new Promise(r=>setTimeout(r,3000));
    return {href:location.href,text:document.body.innerText.slice(0,200),token:!!localStorage.getItem('gsb_hr_token')};
  })()` });
  console.log('login result', JSON.stringify(login));
  for (const [name, route] of [['dashboard','/dashboard'],['employees','/employees'],['approvals','/approvals'],['payroll','/payroll'],['organization','/organization']]) {
    await cmd('Runtime.evaluate', { expression: `window.history.pushState({},'', '${route}'); window.dispatchEvent(new PopStateEvent('popstate'));` });
    await sleep(2800);
    const shot = await cmd('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    fs.writeFileSync(path.join(outDir, `${name}.png`), Buffer.from(shot.data, 'base64'));
    const state = await cmd('Runtime.evaluate', { expression: `({href:location.href,title:document.title,text:document.body.innerText.slice(0,60)})`, returnByValue: true });
    console.log(name, JSON.stringify(state));
  }
} finally { try { ws?.close(); } catch {}; child.kill(); }
