{"cmd": "@'
const base = 'http://localhost:3000/api';
async function call(path, { method = 'GET', token, body } = {}) {
  const response = await fetch(base + path, {
    method,
    headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined
  });
  const payload = await response.json();
  return { status: response.status, payload };
}
(async () => {
  const employeeLogin = await call('/auth/login', { method: 'POST', body: { username: 'employee', password: 'Employee@123' } });
  const hrLogin = await call('/auth/login', { method: 'POST', body: { username: 'hr', password: 'Hr@123' } });
  const adminLogin = await call('/auth/login', { method: 'POST', body: { username: 'admin', password: 'Admin@123' } });
  const employeeToken = employeeLogin.payload.data.token;
  const hrToken = hrLogin.payload.data.token;
  const adminToken = adminLogin.payload.data.token;
  const forbidden = await call('/employees', { token: employeeToken });
  const usedDepartmentDelete = await call('/org/4', { method: 'DELETE', token: hrToken, body: { confirm: true } });
  const draft = await call('/leaves', { method: 'POST', token: employeeToken, body: { type: 'annual', start_time: '2026-10-20 09:00:00', end_time: '2026-10-20 18:00:00', reason: '集成测试', submit: false } });
  const submitted = await call(`/leaves/${draft.payload.data.id}/submit`, { method: 'POST', token: employeeToken, body: {} });
  const approved = await call(`/leaves/${draft.payload.data.id}/decision`, { method: 'POST', token: hrToken, body: { decision: 'approve', comment: '集成测试通过' } });
  const generated = await call('/payrolls/generate', { method: 'POST', token: hrToken, body: { month: '2026-11' } });
  const reset = await call('/system/reset-demo', { method: 'POST', token: adminToken, body: { confirm: 'RESET' } });
  console.log(JSON.stringify({
    logins: [employeeLogin.status, hrLogin.status, adminLogin.status],
    employeeManagementStatus: forbidden.status,
    departmentDeleteBlocked: { status: usedDepartmentDelete.status, message: usedDepartmentDelete.payload.error?.message },
    leaveStateFlow: [draft.payload.data?.status, submitted.payload.data?.status, approved.payload.data?.status],
    payrollGenerated: { status: generated.status, created: generated.payload.data?.created, skipped: generated.payload.data?.skipped },
    resetStatus: reset.status
  }, null, 2));
})().catch((error) => { console.error(error); process.exit(1); });
